func GroupByErr[T any, U comparable, Slice ~[]T](collection Slice, iteratee func(item T) (U, error)) (map[U]Slice, error) {
	result := map[U]Slice{}

	for i := range collection {
		key, err := iteratee(collection[i])
		if err != nil {
			return nil, err
		}

		result[key] = append(result[key], collection[i])
	}

	return result, nil
}
