func CrossJoinBy3[A, B, C, Out any](listA []A, listB []B, listC []C, transform func(a A, b B, c C) Out) []Out {
	size := len(listA) * len(listB) * len(listC)
	if size == 0 {
		return []Out{}
	}

	result := make([]Out, 0, size)

	for _, a := range listA {
		for _, b := range listB {
			for _, c := range listC {
				result = append(result, transform(a, b, c))
			}
		}
	}

	return result
}
```

