func TrimSuffix[T comparable, I ~func(func(T) bool)](collection I, suffix []T) I {
	n := len(suffix)
	if n == 0 {
		return collection
	}

	return func(yield func(T) bool) {
		var i int
		for item := range collection {
			if item == suffix[i%n] {
				i++
				continue
			}

			for j := range i {
				if !yield(suffix[j%n]) {
					return
				}
			}

			i = 0
			if item == suffix[0] {
				i++
				continue
			}

			if !yield(item) {
				return
			}
		}
		if i%n != 0 {
			for j := range i {
				if !yield(suffix[j%n]) {
					return
				}
			}
		}
	}
}
```

