func sumUint32(s []uint32) uint32 {
	var acc simd.Uint32s
	lanes := acc.Len()

	i := 0
	for ; i+lanes <= len(s); i += lanes {
		acc = acc.Add(simd.LoadUint32s(s[i : i+lanes]))
	}
	if i < len(s) {
		v, _ := simd.LoadUint32sPart(s[i:])
		acc = acc.Add(v)
	}

	var buf [maxLanes32]uint32
	acc.Store(buf[:])
	var total uint32
	for k := range lanes {
		total += buf[k]
	}
	return total
}
