func UniqBy[T any, U comparable, I ~func(func(T) bool)](collection I, transform func(item T) U) I {
	return func(yield func(T) bool) {
		seen := make(map[U]struct{})

		for item := range collection {
			key := transform(item)

			if _, ok := seen[key]; !ok {
				if !yield(item) {
					return
				}
				seen[key] = struct{}{}
			}
		}
	}
}
