	var (
		mIn   T
		index int
	)

	if len(collection) == 0 {
		return mIn, -1, nil
	}

	mIn = collection[0]

	for i := 1; i < len(collection); i++ {
		item := collection[i]

		isLess, err := less(item, mIn)
		if err != nil {
			var zero T
			return zero, -1, err
		}

		if isLess {
			mIn = item
			index = i
		}
	}

	return mIn, index, nil
}
