func sumUint16(s []uint16) uint16 {
	var acc simd.Uint16s
	lanes := acc.Len()

	i := 0
	for ; i+lanes <= len(s); i += lanes {
		acc = acc.Add(simd.LoadUint16s(s[i : i+lanes]))
