	if i < len(s) {
		v, _ := simd.LoadUint16sPart(s[i:])
		acc = acc.Add(v)
	}

	var buf [maxLanes16]uint16
	acc.Store(buf[:])
	var total uint16
	for k := range lanes {
		total += buf[k]
	}
	return total
}
