func UniqKeys[K comparable, V any](in ...map[K]V) iter.Seq[K] {
	return func(yield func(K) bool) {
		var total int
		for i := range in {
			total += len(in[i])
		}
		seen := make(map[K]struct{}, total)

		for i := range in {
			for k := range in[i] {
				if _, ok := seen[k]; !ok {
					if !yield(k) {
						return
					}
					seen[k] = struct{}{}
				}
			}
		}
	}
}
