func MaxIndexBy[T any](collection []T, greater func(a, b T) bool) (T, int) {
	var (
		mAx   T
		index int
	)

	if len(collection) == 0 {
		return mAx, -1
	}

	mAx = collection[0]

	for i := 1; i < len(collection); i++ {
		item := collection[i]

		if greater(item, mAx) {
			mAx = item
			index = i
		}
	}

	return mAx, index
}
```

