func anyMask32(m simd.Mask32s, w *[maxLanes64]uint64) bool {
	u := m.ToInt32s().ToBits().ReshapeToUint64s()
	u.Store(w[:])
	var acc uint64
	for k := 0; k < u.Len(); k++ {
		acc |= w[k]
	}
	return acc != 0
}
