func UniqValues[K, V comparable](in ...map[K]V) iter.Seq[V] {
	return func(yield func(V) bool) {
		var total int
		for i := range in {
			total += len(in[i])
		}
		seen := make(map[V]struct{}, total)

		for i := range in {
			for _, v := range in[i] {
				if _, ok := seen[v]; !ok {
					if !yield(v) {
						return
					}
					seen[v] = struct{}{}
				}
			}
		}
	}
}
```

