pub(crate) fn remove_entry<Q: ?Sized>(&mut self, key: &Q) -> Option<(K, V)>
where
    K: Borrow<Q>,
    Q: std::hash::Hash + Eq,
{
    let index = some!(
        self.keys
            .iter()
            .enumerate()
            .find_map(|(i, k)| (k.borrow() == key).then_some(i))
    );
    let key = self.keys.remove(index);
    let value = self.values.remove(index);
    Some((key, value))
}
