pub(crate) fn synopsis(roff: &mut Roff, cmd: &clap::Command) {
    let name = cmd.get_bin_name().unwrap_or_else(|| cmd.get_name());

    if let Some(usage) = cmd.get_overridden_usage() {
        override_synopsis(roff, name, &usage.to_string());
        return;
    }

    let mut line = vec![bold(name), roman(" ")];

    let required_groups: Vec<Vec<&Arg>> = cmd
        .get_groups()
        .filter(|g| g.is_required_set())
        .map(|g| unroll_group_args(cmd, g.get_id()))
        .filter(|members| !members.is_empty())
        .collect();
    let group_members: Vec<&Arg> = required_groups.iter().flatten().copied().collect();

    let mut opts: Vec<_> = cmd
        .get_arguments()
        .filter(|i| {
            !i.is_hide_set()
                && !i.is_positional()
                && !group_members.iter().any(|gm| gm.get_id() == i.get_id())
        })
        .collect();

    opts.sort_by_key(|opt| option_sort_key(opt));

    for opt in opts.iter().filter(|opt| !opt.is_required_set()) {
        render_synopsis_option(&mut line, opt);
    }

    for opt in opts.iter().filter(|opt| opt.is_required_set()) {
        render_synopsis_option(&mut line, opt);
    }

    for members in &required_groups {
        line.push(roman("<"));
        for (i, arg) in members.iter().enumerate() {
            if i > 0 {
                line.push(roman("|"));
            }
            line.extend(render_synopsis_arg(arg));
        }
        line.push(roman(">"));
        line.push(roman(" "));
    }

    for arg in cmd.get_positionals().filter(|arg| !arg.is_hide_set()) {
        if group_members.iter().any(|gm| gm.get_id() == arg.get_id()) {
            continue;
        }

        let (lhs, rhs) = option_markers(arg);
        line.push(roman(lhs));
        if let Some(value) = arg.get_value_names() {
            line.push(italic(value.join(" ")));
        } else {
            line.push(italic(arg.get_id().as_str()));
        }
        line.push(roman(rhs));
        line.push(roman(" "));
    }

    if cmd.has_subcommands() {
        let (lhs, rhs) = subcommand_markers(cmd);
        line.push(roman(lhs));
        line.push(italic(
            cmd.get_subcommand_value_name()
                .unwrap_or_else(|| subcommand_heading(cmd))
                .to_lowercase(),
        ));
        line.push(roman(rhs));
    }

    roff.text(line);
}
