func run(identifier: String) {
    let group = MultiThreadedEventLoopGroup(numberOfThreads: 1)
    let loop = group.next()
    let dg = DispatchGroup()

    measure(identifier: identifier) {
        for _ in 0..<10000 {
            dg.enter()
            loop.execute { dg.leave() }
        }
        dg.wait()
        return 10_000
    }

    try! group.syncShutdownGracefully()
}
