            backPressureStrategy: backPressureStrategy,
            buffer: buffer,
            continuation: nil,  // Setting this to nil since we are resuming the continuation
            hasOutstandingDemand: shouldProduceMore,
            iteratorInitialized: iteratorInitialized
        )

