            count &+= headers[canonicalForm: "key"].count
        }
        return count
    }

    measure(identifier: identifier + "_trimming_whitespace") {
        let headers: HTTPHeaders = ["key": "         some   ,   trimming     "]
        var count = 0
        for _ in 0..<100_000 {
            count &+= headers[canonicalForm: "key"].count
