search() {
  const search: { [index: string]: string|undefined } = {};
  const path = this.location.path();
  const q = path.indexOf('?');
  if (q > -1) {
    try {
        const params = path.substr(q + 1).split('&');
        params.forEach(p => {
          const pair = p.split('=');
          if (pair[0]) {
            search[decodeURIComponent(pair[0])] = pair[1] && decodeURIComponent(pair[1]);
          }
        });
    } catch (e) { /* don't care */ }
  }
  return search;
}
