parse(dateString: string, token: string, match: Match): ParseResult<number> {
  const valueCallback = (value: number) => {
    if (value === 0) {
      return 7;
    }
    return value;
  };

  switch (token) {
    // 2
    case "i":
    case "ii": // 02
      return parseNDigits(token.length, dateString);
    // 2nd
    case "io":
      return match.ordinalNumber(dateString, { unit: "day" });
    // Tue
    case "iii":
      return mapValue(
        match.day(dateString, {
          width: "abbreviated",
          context: "formatting",
        }) ||
          match.day(dateString, {
            width: "short",
            context: "formatting",
          }) ||
          match.day(dateString, {
            width: "narrow",
            context: "formatting",
          }),
        valueCallback,
      );
    // T
    case "iiiii":
      return mapValue(
        match.day(dateString, {
          width: "narrow",
          context: "formatting",
        }),
        valueCallback,
