      "o " +
      suffixPreposition(preposition) +
      declension(scheme, count, "future")
    );
  } else {
    return (
      prefixPreposition(preposition) +
      "pred " +
      suffixPreposition(preposition) +
      declension(scheme, count, "past")
    );
  }
};
