auto format(const std::filesystem::path& p, FormatContext& ctx) const {
  auto specs = specs_;
  auto path_string =
      !path_type_ ? p.native()
                  : p.generic_string<std::filesystem::path::value_type>();

  detail::handle_dynamic_spec(specs.dynamic_width(), specs.width, width_ref_,
