private fun tryPush(instance: T): Boolean {
    var index = ((System.identityHashCode(instance) * MAGIC) ushr shift) + 1
    repeat(PROBE_COUNT) {
        if (instances.compareAndSet(index, null, instance)) {
            pushTop(index)
