            "HEAD" -> option(CURLOPT_NOBODY, 1L)

            else -> {
                if (size > 0) {
                    option(CURLOPT_POST, 1L)
                    option(CURLOPT_POSTFIELDSIZE_LARGE, size)
                }
                option(CURLOPT_CUSTOMREQUEST, method)
            }
        }
    }
}
