override suspend fun awaitContent(min: Int): Boolean {
    rethrowCloseCauseIfNeeded()
    if (_readBuffer.size >= min) return true

    sleepWhile(Slot::Read) {
        flushBufferSize + _readBuffer.size < min && _closedCause.value == null
    }
