protected function addWhere($query, $key, $extraValue)
{
    if ($extraValue === 'NULL') {
        $query->whereNull($key);
    } elseif ($extraValue === 'NOT_NULL') {
        $query->whereNotNull($key);
    } elseif (str_starts_with($extraValue, '!')) {
        $query->where($key, '!=', mb_substr($extraValue, 1));
    } else {
        $query->where($key, $extraValue);
    }
}
