protected function retryOnceOnLostConnection(Closure $callback)
{
    $retries = 1;

    while (true) {
        try {
            return $callback();
        } catch (RedisClusterException|RedisException|ErrorException $e) {
            if (! $this->causedByLostConnection($e)) {
                throw $e;
            }

            $this->rebuildClient();

            if ($retries-- === 0) {
                throw $e;
            }
        }
    }
}
